    [5320]={name="Padded Lamellar Boots",quality=2,ilvl=16,sourceType="quest_reward",instructions="Reward from the quest 'Stolen Booty'. Pick it over the other reward choices.",zone="The Barrens",questName="Stolen Booty",lore="While I'd like to recover all my goods, I'm sure that's not possible. Still, there's a few things that I absolutely must have! As you see, my observatory is ready to go, but it needs the smaller of the two lenses."},
    [5324]={name="Engineer's Hammer",quality=2,ilvl=16,sourceType="quest_reward",instructions="Reward from the quest 'Samophlange'. Pick it over the other reward choices.",zone="The Barrens",questName="Samophlange",lore="Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose."},
    [5325]={name="Welding Shield",quality=2,ilvl=16,sourceType="quest_reward",instructions="Reward from the quest 'Samophlange'. Pick it over the other reward choices.",zone="The Barrens",questName="Samophlange",lore="Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose."},
    [5328]={name="Cinched Belt",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'The Disruption Ends'. Pick it over the other reward choices.",zone="The Barrens",questName="The Disruption Ends",lore="One of my scouts witnessed an attack on a caravan from Durotar. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout."},
    [5340]={name="Cauldron Stirrer",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Apothecary Zamah'.",zone="The Barrens",questName="Apothecary Zamah",lore="I have rendered the spores you gave me into an emulsion. I must now send it to my associate, Apothecary Zamah. If you were to carry this to her, she can offer you something from our stores of alchemical goods."},
    [5343]={name="Barkeeper's Cloak",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'Raptor Horns'.",zone="The Barrens",questName="Raptor Horns",lore="The raptors of the Barrens are smarter than raptors in other lands. And I think all that smarts is hiding in their horns!"},
    [5346]={name="Orcish Battle Bow",quality=2,ilvl=14,sourceType="quest_reward",instructions="Reward from the quest 'Centaur Bracers'. Pick it over the other reward choices.",zone="The Barrens",questName="Centaur Bracers",lore="The Kolkar are a threat to the Horde's claims in the Barrens; we must reduce the numbers of their troops. And so, I have a bounty task for you."},
    [5351]={name="Bounty Hunter's Ring",quality=2,ilvl=20,sourceType="quest_reward",instructions="Reward from the quest 'Hezrul Bloodmark'.",zone="The Barrens",questName="Hezrul Bloodmark",lore="Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens. He is fierce, brutal and cunning. Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us."},
    [5443]={name="Gold-plated Buckler",quality=3,ilvl=20,reqLevel=15,sourceType="boss_drop",instructions="Drops from Miner Johnson.",zone="The Deadmines",npc="Miner Johnson"},
    [5944]={name="Greaves of the People's Militia",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Red Leather Bandanas'. Pick it over the other reward choices.",zone="Westfall",questName="Red Leather Bandanas",lore="The Defias Front is constantly shifting. I've been following their movements for quite some time now. On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear."},
