    [21126]={name="Death's Sting",quality=4,ilvl=84,reqLevel=60,sourceType="boss_drop",instructions="Drops from C'Thun.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [21134]={name="Dark Edge of Insanity",quality=4,ilvl=84,reqLevel=60,sourceType="boss_drop",instructions="Drops from C'Thun.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped.",proc="Chance on hit: Disorients the target, causing it to wander aimlessly for up to 3 sec."},
    [21180]={name="Earthstrike",quality=4,ilvl=66,sourceType="quest_reward",instructions="Reward from the quest 'Champion's Battlegear'. Pick it over the other reward choices.",zone="Silithus",questName="Champion's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show. You'd be wise to hold on to them.",proc="Use: Increases your melee and ranged attack power by 280. Â Effect lasts for 20 sec. (2 Min Cooldown)"},
    [21184]={name="Deeprock Bracers",quality=4,ilvl=62,sourceType="quest_reward",instructions="Reward from the quest 'Stalwart's Battlegear'. Pick it over the other reward choices.",zone="Silithus",questName="Stalwart's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show. You'd be wise to hold on to them."},
    [21244]={name="Blessed Qiraji Pugio",quality=4,ilvl=79,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Imperial Qiraji Armaments'. Pick it over the other reward choices.",zone="Ahn'Qiraj",questName="Imperial Qiraji Armaments",lore="We have not sat idly by for a millennium. We have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world."},
    [21269]={name="Blessed Qiraji Bulwark",quality=4,ilvl=79,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Imperial Qiraji Armaments'. Pick it over the other reward choices.",zone="Ahn'Qiraj",questName="Imperial Qiraji Armaments",lore="We have not sat idly by for a millennium. We have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world."},
    [21316]={name="Leggings of the Ursa",quality=2,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Deadwood of the North'. Pick it over the other reward choices.",zone="Timbermaw Hold",questName="Deadwood of the North",lore="There is a camp of Deadwood furbolgs directly to our southwest. Corruption permeates the camp, and I wish to put an end to it before they become a problem."},
    [21329]={name="Conqueror's Crown",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Conqueror's Crown'.",zone="Ahn'Qiraj",questName="Conqueror's Crown",lore="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."},
    [21330]={name="Conqueror's Spaulders",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Conqueror's Spaulders'.",zone="Ahn'Qiraj",questName="Conqueror's Spaulders",lore="It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon."},
    [21331]={name="Conqueror's Breastplate",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Conqueror's Breastplate'.",zone="Ahn'Qiraj",questName="Conqueror's Breastplate",lore="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."},
    [21332]={name="Conqueror's Legguards",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Conqueror's Legguards'.",zone="Ahn'Qiraj",questName="Conqueror's Legguards",lore="You seek to prove your worth to my kind, mortal? Very well, perhaps we can be of mutual assistance. The ancient sandworm, Ouro, is a being of legendary power."},
    [21333]={name="Conqueror's Greaves",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Conqueror's Greaves'.",zone="Ahn'Qiraj",questName="Conqueror's Greaves",lore="Qiraji magic is strong and ancient. The most powerful qiraji wield items of such might, they'd give pause even to a dragon."},
    [21394]={name="Drape of Unyielding Strength",quality=4,ilvl=67,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Drape of Unyielding Strength'.",zone="Ahn'Qiraj",questName="Drape of Unyielding Strength",lore="I can make you a protective item that'll be of assistance in the fight against our enemy. I shall need a Qiraji drape, which I'll resize for you of course."},
    [21477]={name="Ring of Fury",quality=3,ilvl=74,reqLevel=60,sourceType="boss_drop",instructions="Drops from Moam.",zone="Ruins of Ahn'Qiraj",npc="Moam",lore="A stone giant pressed into qiraji service, who drains the mana of everyone fighting him and turns to rock when full."},
    [21567]={name="Rune of Duty",quality=3,ilvl=45,reqLevel=40,sourceType="vendor",instructions="Bought from the Warsong Gulch quartermaster with marks of honor. Alliance: Illiyana Moonblaze at Silverwing Grove, Ashenvale. Horde: Kelm Hargunth at Mor'shan Base Camp, The Barrens."},
    [21568]={name="Rune of Duty",quality=3,ilvl=25,reqLevel=20,sourceType="vendor",instructions="Bought from the Warsong Gulch quartermaster with marks of honor. Alliance: Illiyana Moonblaze at Silverwing Grove, Ashenvale. Horde: Kelm Hargunth at Mor'shan Base Camp, The Barrens."},
    [21581]={name="Gauntlets of Annihilation",quality=4,ilvl=88,reqLevel=60,sourceType="boss_drop",instructions="Drops from C'Thun.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [21586]={name="Belt of Never-ending Agony",quality=4,ilvl=88,reqLevel=60,sourceType="boss_drop",instructions="Drops from C'Thun.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [21598]={name="Royal Qiraji Belt",quality=4,ilvl=81,reqLevel=60,sourceType="boss_drop",instructions="Drops from Emperor Vek'lor.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'lor",lore="Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other."},
    [21601]={name="Ring of Emperor Vek'lor",quality=4,ilvl=81,reqLevel=60,sourceType="boss_drop",instructions="Drops from Emperor Vek'lor.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'lor",lore="Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other."},
    [21618]={name="Hive Defiler Wristguards",quality=4,ilvl=78,reqLevel=60,sourceType="boss_drop",instructions="Drops from Princess Huhuran.",zone="Temple of Ahn'Qiraj",npc="Princess Huhuran",lore="A qiraji brood matron whose poison is potent enough that the fight is really a race against her venom."},
    [21664]={name="Barbed Choker",quality=4,ilvl=77,reqLevel=60,sourceType="boss_drop",instructions="Drops from Fankriss the Unyielding.",zone="Temple of Ahn'Qiraj",npc="Fankriss the Unyielding",lore="A vast qiraji burrower that spawns its young mid-fight and hurls intruders into the walls."},
    [21674]={name="Gauntlets of Steadfast Determination",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Battleguard Sartura.",zone="Temple of Ahn'Qiraj",npc="Battleguard Sartura",lore="The qiraji empire's finest soldier, who fights with her honour guard and refuses to be separated from them."},
    [21677]={name="Ring of the Qiraji Fury",quality=4,ilvl=78,reqLevel=60,sourceType="boss_drop",instructions="Drops from Viscidus.",zone="Temple of Ahn'Qiraj",npc="Viscidus",lore="A living mass of qiraji poison. It has to be frozen solid and then shattered, which is not how most things die."},
    [21710]={name="Cloak of the Fallen God",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Savior of Kalimdor'. Pick it over the other reward choices.",zone="Ahn'Qiraj",questName="The Savior of Kalimdor",lore="To the Caverns of Time you go, Lord:Lady;. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection."},
    [21809]={name="Fury of the Forgotten Swarm",quality=3,ilvl=71,reqLevel=60,sourceType="boss_drop",instructions="Drops from Colonel Zerran.",zone="Ruins of Ahn'Qiraj",npc="Colonel Zerran"},
    [21995]={name="Boots of Heroism",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Anthion's Parting Words'.",zone="Ironforge",questName="Anthion's Parting Words",lore="Valthalak's soul was stored in this amulet. In our greed we foolishly split it into three parts, not knowing the curse that would await us. The only way to stop Valthalak's spell is to put the medallion back together."},
    [21997]={name="Breastplate of Heroism",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Saving the Best for Last'.",zone="Ironforge",questName="Saving the Best for Last",lore="That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."},
    [21999]={name="Helm of Heroism",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Saving the Best for Last'.",zone="Ironforge",questName="Saving the Best for Last",lore="That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."},
    [22150]={name="Beads of Ogre Might",quality=3,ilvl=63,sourceType="quest_reward",instructions="Reward from the quest 'Falrin's Vendetta'. Pick it over the other reward choices.",zone="Dire Maul",questName="Falrin's Vendetta",lore="Yet I'm not one to give out favors freely, even if you were sent here by an old friend. I hold nothing but hatred and contempt for our brutish ogre neighbors."},
